    data class Meta(val equipment: String, val secondary: List<String>)

    /** Metadata for an exercise by display name (title-cased slug), or null when it isn't in the dataset. */
    fun forName(name: String): Meta? {
        val slug = name.trim().lowercase().replace(Regex("[^a-z0-9]+"), "-").trim('-')
        val id = ExerciseDemoMapFull.exactSlugToId[slug] ?: return null
        val raw = table[id] ?: return null
        val (eq, sec) = raw.split("|", limit = 2).let { it[0] to it.getOrElse(1) { "" } }
        return Meta(eq, sec.split(",").filter { it.isNotBlank() })
    }
